#!/usr/bin/env python3
import cadquery as cq
from pathlib import Path

SPEC = {'kind': 'extrusion', 'center': [-0.07744124, 0.005564464999999991, -0.376064805], 'basis': [[-0.3126600064765914, 0.005516834769076788, 0.949849085320499], [0.0, 0.9999831333142822, -0.005808019193382827], [-0.949865106396723, -0.0018159353186192422, -0.3126547329385257]], 'axis': [0.949849085320499, -0.005808019193382827, -0.3126547329385257], 'zmin': -0.020682386804021975, 'zmax': 0.02107308317678405, 'profiles': [{'outer': [[-0.014670071778471197, -0.12314655191647417], [-0.018892619017709923, -0.12186477007217794], [0.032489195484156894, 0.003173100600885567], [0.03859777623684193, 0.004639799304247486], [0.03797963362418198, 0.010821700357155146], [0.04188158591984357, 0.015621561290620221], [0.04802820029411033, 0.01627769685851586], [0.052828086971006036, 0.01237569357048974], [0.05348419670565224, 0.006160109963123481], [0.049597142171201335, 0.0013786447602802268], [0.05379500218886816, -0.003145993731011357], [0.002413174467495847, -0.12821838470314983], [-0.001806594203707452, -0.12697248546689469], [-0.04452370528607138, -0.22900336136923705], [-0.04508433714766496, -0.23216936806586577], [-0.047860042343271576, -0.23482779092804387], [-0.051652125864948016, -0.23533600521430628], [-0.055053345283852764, -0.233498619399341], [-0.056695347713764166, -0.23005835991585397], [-0.055991593481669426, -0.22624687309347277], [-0.055100351777881, -0.22539328140723197]], 'holes': []}, {'outer': [[-0.053495361509711896, -0.13978232398886956], [-0.05161984691910134, -0.13359334679488163], [-0.050139321784209843, -0.1154306379531855], [-0.023093642294682092, 0.08046108964859573], [-0.01766460557032581, 0.08796311384516371], [-0.008583232592337967, 0.09354034152546449], [-0.005123069801283506, 0.1015866846341341], [-0.0011834746099555521, 0.11507997170112928], [-0.003302384691018056, 0.12178135188634609], [-0.002660825158950007, 0.12886196285129703], [0.0005966042651383835, 0.13508074607197004], [0.005976361604163209, 0.1396214749590659], [0.010804046499210948, 0.156075416955446], [0.006765897028038243, 0.16090137919938433], [-0.0013777495987756625, 0.16800854017927982], [-0.0065601600850122704, 0.1752143918188178], [-0.008830576596843779, 0.18296317820579988], [-0.011002261178278306, 0.19466039845589034], [-0.011545202046338606, 0.2052718094004256], [-0.012779184090430142, 0.2134154791036728], [-0.013174052777220217, 0.21765994884366555], [-0.01722120590568806, 0.2201276900001938], [-0.01949156473254161, 0.22427349548754696], [-0.019392825964375665, 0.2290707755823433], [-0.016925081478207187, 0.233068579869172], [-0.012779243583104003, 0.23533893922243646], [-0.008090471334311525, 0.2352402284510669], [-0.0040433332445896815, 0.23282181765666873], [0.004396529035252851, 0.22492482012635562], [0.03391112986875144, 0.20271507965138413], [0.04743466190858102, 0.18563819334671378], [0.05084022843357337, 0.17739582266437642], [0.05661510784237586, 0.12349028842868758], [0.05261744865763855, 0.09545642825396262], [0.04304274428643401, 0.05567591769738008], [0.040130837568446626, 0.04466965355187618], [0.035886319447706934, 0.03218271650476411], [-0.02536289135557489, -0.12200389361725464], [-0.02862026609289859, -0.1406116661350573], [-0.03044636184962863, -0.14678108896050218], [-0.03513509728530022, -0.1511737465851194], [-0.04140322396754134, -0.15265443923104105], [-0.047572660087710106, -0.15077898308384408], [-0.052014662517268016, -0.14609024285001143]], 'holes': [[[-0.0456972931321538, -0.1315797186466804], [-0.049398886173007694, -0.1350839886317257], [-0.050822493736349277, -0.13989476709153106], [-0.049694940108097975, -0.1447970128196048], [-0.0461906982786438, -0.14849866451160498], [-0.041353879703798696, -0.14992992687682938], [-0.03641832027651936, -0.14879471715061912], [-0.03271666086395893, -0.14529047722161673], [-0.031244008003161648, -0.1404797892432848], [-0.032420606928868646, -0.13557743303407496], [-0.035924896132727244, -0.13187580124886977], [-0.040761762200827695, -0.13044451897477952]], [[-0.008880186851918772, 0.2324665855820574], [-0.012137626146458098, 0.23256525647988294], [-0.015000292595100852, 0.23098590293735974], [-0.01667831131516129, 0.22822194936441634], [-0.016726799162218108, 0.22502207399570393], [-0.015197585874669404, 0.2221610163553145], [-0.01238431200911072, 0.22043357163899435], [-0.009126878254666338, 0.22038424112128963], [-0.006264243428576879, 0.22196366466332246], [-0.004586164590009969, 0.22472754829123429], [-0.004489209772149155, 0.227928896077], [-0.006066915399854966, 0.23078852119001506]], [[0.0032618631817420006, 0.13288635694072418], [0.000646055391486971, 0.12785211375998684], [0.00015404327185768223, 0.12219422619802493], [0.001880013342468101, 0.11676991929180117], [0.005532309781058365, 0.11242667203885998], [0.010566622225866719, 0.1097614992304015], [0.0162424365982135, 0.10926796495956592], [0.021671583847895592, 0.11099545970830157], [0.02601481002286163, 0.11464777100590297], [0.0286799243399492, 0.11968202410196217], [0.02917194393168309, 0.12534001752587517], [0.027445988512870254, 0.13076423855096087], [0.023793651785031792, 0.13515680624021884], [0.018759360632169514, 0.13777260857688514], [0.013083530507971546, 0.1382661429398981], [0.0076543832582894565, 0.13653866819082508]]]}], 'simplify_tolerance': 9.413498888734856e-05, 'sketch_entity_count': 105}
OUT = Path(__file__).resolve().parent

def vec(v):
    return cq.Vector(float(v[0]), float(v[1]), float(v[2]))

def build():
    s = SPEC
    kind = s["kind"]
    B = s.get("basis")
    center = s.get("center")
    if kind == "extrusion":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["zmin"] * axis[i] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        result = None
        height = s["zmax"] - s["zmin"]
        for profile in s["profiles"]:
            solid = cq.Workplane(plane).polyline(profile["outer"]).close().extrude(height)
            for hole in profile["holes"]:
                cutter = cq.Workplane(plane).polyline(hole).close().extrude(height)
                solid = solid.cut(cutter)
            result = solid if result is None else result.union(solid)
    elif kind == "multi_loft":
        def loft(track):
            wires = [cq.Wire.makePolygon([vec(p) for p in section], close=True) for section in track]
            return cq.Solid.makeLoft(wires, ruled=bool(s.get("ruled", True)))
        outer = [loft(track) for track in s["outer_tracks"]]
        # Keep disjoint solids as a legal STEP compound.  Global Boolean fusion
        # is unnecessary for training geometry and scales poorly with profiles.
        for track in s.get("hole_tracks", []):
            cutter = loft(track)
            cut_outer = []
            for solid in outer:
                try:
                    cut_outer.append(solid.cut(cutter))
                except Exception:
                    cut_outer.append(solid)
            outer = cut_outer
        result = outer[0] if len(outer) == 1 else cq.Compound.makeCompound(outer)
    elif kind == "box":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["mins"][0]*B[i][0] + s["mins"][1]*B[i][1] + s["mins"][2]*B[i][2] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        dx=s["maxs"][0]-s["mins"][0]; dy=s["maxs"][1]-s["mins"][1]; dz=s["maxs"][2]-s["mins"][2]
        result = cq.Workplane(plane).rect(dx,dy,centered=False).extrude(dz)
    elif kind == "cylinder":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["zmin"] * axis[i] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        result = cq.Workplane(plane).circle(s["radius"]).extrude(s["zmax"]-s["zmin"])
    else:
        raise ValueError(kind)
    cq.exporters.export(result, str(OUT / "reconstructed.step"))
    cq.exporters.export(result, str(OUT / "reconstructed.stl"), tolerance=0.001, angularTolerance=0.05)
    return result

if __name__ == "__main__":
    build()
